  const svg = (id, cls = "") => {
    const [box, d] = ICONS[id];
    return `<svg class="ic ${cls}" viewBox="${box}" aria-hidden="true"><path fill="currentColor" d="${d}"/></svg>`;
  };
  /* An item's icon as markup: its drawn icon, tinted by family where the page asks, or its text symbol if it has none. */
  const of = item => (ICONS[item.id] ? svg(item.id, item.family ? `fam-${item.family}` : "") : item.icon);
  const family = f => (ICONS[`family-${f.id}`] ? svg(`family-${f.id}`, `fam-${f.id}`) : f.icon);
  /* A starting deck's icon: drawn if it has one (map key deck-<id>), else its text symbol. */
  const deck = k => (ICONS[`deck-${k.id}`] ? svg(`deck-${k.id}`) : k.icon);
  window.SlotchinkoIcons = { has: id => id in ICONS, of, family, deck };
